list_currencies.code:
import (
	"fmt"
)

resp, err := client.Currencies().ListCurrencies(ctx, map[string]any{"search": "dollar", "active": true}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["currencies"].([]any) {
	currency := row.(map[string]any)
	fmt.Println(currency["id"], currency["code"], currency["name"], currency["conversion_rate"], currency["base"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

